def _associate_chunks_to_workers(
    num_workers: int, worker_env: _WorkerEnv, chunks_replica: List[int], intervals_replica: List[Any]
) -> Any:

    # Initialize the workers_chunks and workers_intervals dictionaries
    workers_chunks = {i: [] for i in range(num_workers)}
    workers_intervals = {i: [] for i in range(num_workers)}

    # Iterate over the chunks and intervals
    for i, (chunk_index, chunk_interval) in enumerate(zip(chunks_replica, intervals_replica)):

        # Determine the worker index for the current chunk and interval
        worker_idx = i % num_workers

        # Append the current chunk and interval to the corresponding worker's lists
        workers_chunks[worker_idx].append(chunk_index)
        workers_intervals[worker_idx].append(chunk_interval)

    # Assign the lists of workers_chunks and workers_intervals to the dictionaries
    for worker_idx in range(num_workers):
        if workers_chunks[worker_idx]:
            workers_chunks[worker_idx] = list(set(workers_chunks[worker_idx]))
            workers_intervals[worker_idx] = list(set(workers_intervals[worker_idx]))

    # Return the workers_chunks and workers_intervals dictionaries as a tuple
    return workers_chunks, workers_intervals
