class TensorSerializer(Serializer):
    def __init__(self) -> None:
        super().__init__()
        self._dtype_to_indices = {v: k for k, v in _TORCH_DTYPES_MAPPING.items()}

    def serialize(self, item: torch.Tensor) -> Tuple[bytes, Optional[str]]:
        dtype_index = self._dtype_to_indices[item.dtype]
        shape_and_data = [dtype_index.to_bytes(4, 'little')]
        shape_length = len(item.shape)
        shape_and_data.append(shape_length.to_bytes(4, 'little'))
        for dim in item.shape:
            shape_and_data.append(dim.to_bytes(4, 'little'))
        raw_data = item.numpy().astype(numpy.float32).tobytes()
        shape_and_data.append(raw_data)
        return b''.join(shape_and_data), None
