def _upload_fn(upload_queue: Queue, remove_queue: Queue, cache_dir: str, output_dir: Dir) -> None:

    from urllib.parse import urlparse
    from litdata.streaming.client import S3Client

    scheme = urlparse(output_dir).scheme

    if scheme == "s3":
        s3_client = S3Client.client()

    while True:
        try:
            item = upload_queue.get(block=True, timeout=1)
        except queue.Empty:
            continue

        if isinstance(item, str):
            file_path = item
            abs_file_path = os.path.abspath(file_path)
            if not abs_file_path.startswith(cache_dir):
                file_path = os.path.join(cache_dir, os.path.relpath(file_path, os.path.dirname(abs_file_path)))
        elif isinstance(item, tuple):
            temp_dir, file_path = item
            abs_temp_dir = os.path.abspath(temp_dir)
            if not abs_temp_dir.startswith(cache_dir):
                temp_dir = os.path.join(cache_dir, os.path.relpath(temp_dir, os.path.dirname(abs_temp_dir)))

        if scheme == "s3":
            # Upload to S3
            s3_client.upload_file(file_path, output_dir.netloc, output_dir.path.lstrip("/"))
            remove_queue.put(file_path)
            upload_queue.task_done()

        else:
            # Move or copy file within local filesystem
            shutil.move(file_path, output_dir.path)
            remove_queue.put(file_path)
            upload_queue.task_done()
